fu_uswid_firmware_build(FuFirmware *firmware, XbNode *n, GError **error)
{
        FuUswidFirmware *self = FU_USWID_FIRMWARE(firmware);
        FuUswidFirmwarePrivate *priv = GET_PRIVATE(self);
        const gchar *str;
        guint64 tmp;
